import{_ as s,l as i,o as e,c as l,v as t,p as n,x as r,d as m,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"gem5 与微结构模拟","description":"","frontmatter":{"title":"gem5 与微结构模拟","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gem5-simulation.md","filePath":"cs/gem5-simulation.md","lastUpdated":1789023840000}'),h={name:"cs/gem5-simulation.md"};function p(u,a,A,E,B,_){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="gem5-与微结构模拟" tabindex="-1">gem5 与微结构模拟 <a class="header-anchor" href="#gem5-与微结构模拟" aria-label="Permalink to &quot;gem5 与微结构模拟&quot;">​</a></h1><div class="epigraph"><p>周期级模拟把 ROB、IQ、cache、NoC 变成可改的旋钮；换的是速度与绝对频率不准，换来的是对照实验：只改 TAGE 表项看 CPI。</p><footer>—— 据 Binkert et al., The gem5 Simulator, ACM CAN 2011 整理</footer></div><p><a href="/cs/roofline-model">上一课</a> 需要可信的 \\(F\\) 与 \\(B\\)。<a href="/cs/pmu-counters">PMU</a> 在真机上快，但旋钮不可任意拆。<a href="/cs/spec-benchmark-pitfalls">SPEC 陷阱</a> 在模拟里同样存在，且更易「只跑一小段」。本课缺口是 <strong>gem5：事件驱动的全系统/系统调用模拟，用来做本课序结构的消融。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>真机不能把 <a href="/cs/issue-queue-wakeup">发射宽度</a> 从 4 改成 8 而保持其余不变。RTL 太慢。缺口是<strong>在 C++ 模型里实现流水线与存储层次，用同一检查点比较两种预测器。</strong> gem5 是当代教学与论文常用的这一层，不是唯一模拟器。</p><p><span class="marginnote">Binkert 等描述 gem5 对 M5 与 GEMS 的合并：CPU 模型（Simple、O3）+ 存储（Ruby 等）。绝对 IPC 与硅有差距；排序（A 比 B 好）更可信，仍要校准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选 CPU 模型：功能级快、O3 才有 ROB/IQ/LSQ。挂 cache、预取、可选 Ruby 一致性。跑同一 binary 与输入，dump 误预测、缺失、MLP。对照本课序：改 gshare 历史位、RRIP 插入、目录 vs 窥探。</p>',8)),(e(),n(d,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIN%5B%22%E5%90%8C%E4%B8%80%E4%BA%8C%E8%BF%9B%E5%88%B6%22%5D%20--%3E%20M1%5B%22%E9%85%8D%E7%BD%AE%20A%EF%BC%9A%E5%A6%82%20gshare%22%5D%0A%20%20BIN%20--%3E%20M2%5B%22%E9%85%8D%E7%BD%AE%20B%EF%BC%9A%E5%A6%82%20TAGE%22%5D%0A%20%20M1%20--%3E%20STAT%5B%22CPI%20%2F%20%E7%BC%BA%E5%A4%B1%20%2F%20%E8%AF%AF%E9%A2%84%E6%B5%8B%22%5D%0A%20%20M2%20--%3E%20STAT%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>模拟器自己的 <a href="/cs/roofline-model">Roofline</a> 必须用模型里的带宽，不能抄产品手册当硅。Warmup：丢掉冷 cache 段，否则与 SPEC 短跑陷阱同类。全系统模式才看 OS <a href="/cs/tlb-shootdown">TLB shootdown</a>；syscall 模式更快但不含内核。可靠性下一课：模拟通常假定无软错误，MTTF 要另加故障模型。</p><p>采样（SimPoint 一类）用代表性区间代替全程序，否则 O3 模型跑 SPEC 要以天计。区间选错会让「TAGE 赢 gshare」变成那段热循环的性质，而不是整程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不教安装与命令行。也不把 FPGA 原型当 gem5 的替代公式——更快更准、更贵。Spectre 课会警告：模拟器若无时序 cache 模型就看不到侧信道，那是安全与模型保真的交叉。</p><p>后课默认：结构消融用周期级模拟；硅上的错误率用 MTTF 与冗余另算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>gem5 一类模拟器用可重复旋钮解释 CPI 来源。</li><li>绝对数要校准；短 warmup 会骗人。</li><li>故障与冗余是下一课 MTTF。</li><li>出处：Binkert et al., <em>ACM CAN</em>, 2011。</li></ul>',8))])}const g=s(h,[["render",p]]);export{f as __pageData,g as default};
